export const PRACTICE_NAMES={breath:'호흡 알아차리기',body:'몸의 감각 살피기',thought:'떠오르는 생각 바라보기'};
export const ANCHOR='원하지 않는 생각이나 감정이 불쑥 떠오르더라도, 어떠한 평가나 판단 없이 있는 그대로 바라보아도 좋습니다. 그리고 다시 지금의 호흡에 주의를 돌려보아도 좋습니다.';
// Caption and narration share the same cue ID and explicit window. Remaining time is silence.
export function timeline(practice, minutes) {
  return SCRIPTS[practice][minutes].map(([at, text], i, rows) => {
    if(i===Math.floor(rows.length/2)) text=ANCHOR;
    const next=rows[i+1]?.[0]??minutes*60;
    const clip=NARRATION[`${practice}-${minutes}`]?.clips?.[`${practice}-${minutes}-${i}`];
    return {id:`${practice}-${minutes}-${i}`, at, until:Math.min(next-3,at+(clip?.duration??Math.max(9,Math.min(26,text.length*.27)))), text};
  });
}
export function cueAt(cues, seconds) {return cues.find(c=>seconds>=c.at&&seconds<c.until)??null;}
